/* =====================================================================================================
 * DMF0082_1104 클라우드 이관 · 90_VERIFY — 적용 확인 (조회 전용)
 * 마커 [E20261104-DMF0082ONEQUERY] · 생성 2026-11-09 13:09:09 (사내 ZIOUI1) · 실행 계정 = SCM_MGR · 파일 전체 F5 · 값 입력 없음
 * 대상 = 새 객체 PKG_DMF0082_1104 만. 원본 PKG_DMF0082 는 변경하지 않는다.
 * ===================================================================================================== */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

-- V1 상태 — 기대: PACKAGE · PACKAGE BODY 모두 VALID
SELECT 'V1' CHK, OBJECT_NAME, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0082_1104' ORDER BY OBJECT_TYPE;
-- V2 컴파일 오류 — 기대: ERR_CNT 0
SELECT 'V2' CHK, COUNT(*) ERR_CNT, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL — 20 의 C2 오류 목록 회신' END JUDGE FROM USER_ERRORS WHERE NAME = 'PKG_DMF0082_1104';
-- V3 원문이 사내 apply #26 과 같은지 — 정규화 지문(줄 수 · 길이 합 · ORA_HASH 합) · 사내 값 = 생성 시 측정(2026-11-09 13:09:09)
SELECT 'V3' CHK, TYPE, COUNT(*) N_LINES, SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))) LEN_SUM, SUM(ORA_HASH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))) HASH_SUM,
       DECODE(TYPE, 'PACKAGE', 104, 27888) CORP_N, DECODE(TYPE, 'PACKAGE', 7660, 1548471) CORP_LEN, DECODE(TYPE, 'PACKAGE', 225891144160, 60508527752322) CORP_HASH,
       CASE WHEN COUNT(*) = DECODE(TYPE, 'PACKAGE', 104, 27888) AND SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))) = DECODE(TYPE, 'PACKAGE', 7660, 1548471)
                 AND SUM(ORA_HASH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))) = DECODE(TYPE, 'PACKAGE', 225891144160, 60508527752322) THEN 'PASS'
            WHEN COUNT(*) = DECODE(TYPE, 'PACKAGE', 104, 27888) AND SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))) = DECODE(TYPE, 'PACKAGE', 7660, 1548471) THEN 'PASS? (줄·길이 같음 · 해시만 다름)'
            ELSE 'FAIL — 파일 일부만 실행됐거나 다른 원문' END JUDGE
  FROM USER_SOURCE WHERE NAME = 'PKG_DMF0082_1104' AND TYPE IN ('PACKAGE','PACKAGE BODY') AND RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)) IS NOT NULL GROUP BY TYPE ORDER BY TYPE;
-- V4 권한 — 원본 PKG_DMF0082 에 있는데 PKG_DMF0082_1104 에 없는 권한 (기대 0행 · 측정에는 무관)
SELECT 'V4' CHK, O.GRANTEE, O.PRIVILEGE, '1104 에 없음' JUDGE FROM USER_TAB_PRIVS_MADE O
 WHERE O.TABLE_NAME = 'PKG_DMF0082' AND NOT EXISTS (SELECT 1 FROM USER_TAB_PRIVS_MADE N WHERE N.TABLE_NAME = 'PKG_DMF0082_1104' AND N.GRANTEE = O.GRANTEE AND N.PRIVILEGE = O.PRIVILEGE);
-- V5 시노님 — 원본에 있는데 1104 에 없는 시노님 (기대 0행 · 측정에는 무관)
SELECT 'V5' CHK, O.OWNER, '1104 시노님 없음' JUDGE FROM ALL_SYNONYMS O
 WHERE O.TABLE_OWNER = USER AND O.TABLE_NAME = 'PKG_DMF0082' AND O.OWNER <> 'PUBLIC'
   AND NOT EXISTS (SELECT 1 FROM ALL_SYNONYMS N WHERE N.OWNER = O.OWNER AND N.TABLE_OWNER = USER AND N.TABLE_NAME = 'PKG_DMF0082_1104');
-- V6 원본 PKG_DMF0082 무변경 — LAST_DDL 이 00 P1 때와 같아야 한다
SELECT 'V6' CHK, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0082' ORDER BY OBJECT_TYPE;
